import * as THREE from 'three/webgpu';
import { texture as tslTexture } from 'three/tsl';

export default function createNode(config, ctx) {
  const container = new THREE.Object3D();
  container.position.set(0, 3, 0);
  container.rotation.set(0, 0, 0);
  container.scale.set(1, 1, 1);

  // Load texture
  const textureUrl = config.assets?.imageUrl || '/prism-assets/chrome/ceramic-grain.map.png';
  const texture = ctx.textureLoader.load(textureUrl);
  texture.colorSpace = THREE.SRGBColorSpace;

  // Create plane geometry with aspect ratio 512:320
  const aspectRatio = 512 / 320;
  const height = 0.6;
  const width = height * aspectRatio;

  const geometry = new THREE.PlaneGeometry(width, height);

  // Create material with TSL texture node
  const colorNode = tslTexture(texture);
  const material = new THREE.MeshBasicNodeMaterial({
    colorNode: colorNode,
    side: THREE.DoubleSide,
  });

  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.z = 0;
  mesh.renderOrder = 0;
  container.add(mesh);

  // Extract text content
  let textContent = 'Features';
  if (config.textContent) {
    if (Array.isArray(config.textContent) && config.textContent.length > 0) {
      const first = config.textContent[0];
      textContent = (typeof first === 'object' ? first.text : first) || 'Features';
    } else if (typeof config.textContent === 'string') {
      textContent = config.textContent;
    }
  }

  // Render text using fontAtlas
  if (ctx.fontAtlas) {
    const textMesh = ctx.fontAtlas.createTextMesh(textContent, {
      font: 'Lora',
      size: 0.34,
      weight: 400,
      color: '#16161d',
    });

    textMesh.position.z = 0.01;
    textMesh.renderOrder = 1;
    container.add(textMesh);
  }

  // Cleanup function
  container.userData.cleanup = () => {
    texture.dispose();
    geometry.dispose();
    material.dispose();
  };

  // Handlers object
  container.userData.handlers = {};

  return container;
}
